<script setup lang="ts">
import {computed} from 'vue'
import {useLegacyChatActionsStore} from '@/stores/legacyChatActions'
import {useLegacyChatRedPacketsStore} from '@/stores/legacyChatRedPackets'
import {useChatStore} from '@/stores/chat'
const actions=useLegacyChatActionsStore(),packets=useLegacyChatRedPacketsStore(),chat=useChatStore(),pending=computed(()=>{const p=actions.pending;return p&&(p.kind==='packetCreate'||p.kind==='packetClaim')?p:null}),completed=computed(()=>{const c=actions.completed;return c&&(c.kind==='packetCreate'||c.kind==='packetClaim')?c:null})
</script>
<template><div v-if="pending||completed||actions.error&&(actions.errorKind==='packetCreate'||actions.errorKind==='packetClaim')" class="packet-recovery"><p v-if="actions.error" role="alert">{{ actions.error }}</p><div v-if="pending" role="status"><p>{{ pending.kind==='packetCreate'?'红包创建':'红包 '+pending.id+' 领取' }}结果未确认。旧接口没有幂等恢复，不会自动重发。</p><details><summary>查看原操作字段</summary><pre>{{ JSON.stringify(pending.input,null,2) }}</pre></details><button type="button" :disabled="actions.busy" @click="chat.refreshMessages">重读当前消息</button><button v-if="pending.kind==='packetClaim'" type="button" @click="packets.open(pending.id)">核对当前领取记录</button><button type="button" :disabled="actions.busy" @click="actions.release">我已核对，解除锁定</button></div><p v-if="completed" role="status">{{ completed.kind==='packetCreate'?'红包创建已确认。':'领取请求已返回，是否到账请核对当前详情。' }}实际扣款、税额及积分变化以当前记录为准。</p><button v-if="completed?.kind==='packetClaim'" type="button" @click="packets.open(completed.id)">查看当前红包</button></div></template>
<style scoped lang="scss">.packet-recovery{box-sizing:border-box;max-width:1100px;width:calc(100% - 24px);margin:8px auto;overflow-wrap:anywhere;font-size:13px}p{margin:6px 0}pre{white-space:pre-wrap;word-break:break-word}[role=alert]{color:#bd503c}button{font:inherit;margin:3px;padding:5px 8px;border:1px solid var(--fp-border);border-radius:5px;background:var(--fp-card);color:var(--fp-text)}</style>
